ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/"deliverables"
NAVY,BLUE,AMBER,INK,MUTED,LIGHT,PALE_BLUE,PALE_AMBER,WHITE="0B1F3A","1D4ED8","F4B400","162235","64748B","E8EEF5","EAF2FF","FFF7D6","FFFFFF"

def font(r,size=11,bold=False,color=INK):
    r.font.name="Calibri"; r._element.get_or_add_rPr().rFonts.set(qn("w:ascii"),"Calibri"); r._element.get_or_add_rPr().rFonts.set(qn("w:hAnsi"),"Calibri"); r.font.size=Pt(size); r.bold=bold; r.font.color.rgb=RGBColor.from_string(color)
def shade(c,fill):
    pr=c._tc.get_or_add_tcPr(); n=pr.find(qn("w:shd"));
    if n is None: n=OxmlElement("w:shd"); pr.append(n)
    n.set(qn("w:fill"),fill)
def geometry(t,widths):
    t.autofit=False; pr=t._tbl.tblPr
    for tag,val in (("tblW",sum(widths)),("tblInd",120)):
        n=pr.find(qn(f"w:{tag}"));
        if n is None: n=OxmlElement(f"w:{tag}"); pr.append(n)
        n.set(qn("w:w"),str(val)); n.set(qn("w:type"),"dxa")
    g=t._tbl.tblGrid
    for x in list(g): g.remove(x)
    for width in widths: n=OxmlElement("w:gridCol"); n.set(qn("w:w"),str(width)); g.append(n)
    for row in t.rows:
        for i,c in enumerate(row.cells):
            pr=c._tc.get_or_add_tcPr(); n=pr.find(qn("w:tcW"));
            if n is None: n=OxmlElement("w:tcW"); pr.append(n)
            n.set(qn("w:w"),str(widths[i])); n.set(qn("w:type"),"dxa")
            mar=pr.first_child_found_in("w:tcMar")
            if mar is None: mar=OxmlElement("w:tcMar"); pr.append(mar)
            for side,val in (("top",80),("start",120),("bottom",80),("end",120)):
                x=mar.find(qn(f"w:{side}"));
                if x is None: x=OxmlElement(f"w:{side}"); mar.append(x)
                x.set(qn("w:w"),str(val)); x.set(qn("w:type"),"dxa")
            c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
def para(d,text,size=11,bold=False,color=INK,after=6,align=None):
    p=d.add_paragraph(); p.paragraph_format.space_after=Pt(after); p.paragraph_format.line_spacing=1.25
    if align is not None:p.alignment=align
    font(p.add_run(text),size,bold,color)
def heading(d,text,level=1): p=d.add_paragraph(style=f"Heading {level}"); p.paragraph_format.keep_with_next=True; p.add_run(text)
def bullet(d,title,detail=""):
    p=d.add_paragraph(style="List Bullet"); p.paragraph_format.space_after=Pt(4); p.paragraph_format.line_spacing=1.25; font(p.add_run(title+(" — " if detail else "")),11,True,NAVY)
    if detail:font(p.add_run(detail))
def grid(d,rows,header=("Item","Behaviour"),widths=(2600,6760)):
    t=d.add_table(rows=0,cols=2); t.style="Table Grid"; cs=t.add_row().cells
    for i,x in enumerate(header):shade(cs[i],NAVY);font(cs[i].paragraphs[0].add_run(x),10,True,WHITE)
    for a,b in rows:
        cs=t.add_row().cells;shade(cs[0],LIGHT);font(cs[0].paragraphs[0].add_run(a),10,True,NAVY);font(cs[1].paragraphs[0].add_run(b),10)
        for c in cs:c.paragraphs[0].paragraph_format.space_after=Pt(0)
    geometry(t,list(widths));d.add_paragraph().paragraph_format.space_after=Pt(1)
def callout(d,label,text,amber=False):
    t=d.add_table(rows=1,cols=1);t.style="Table Grid";geometry(t,[9360]);c=t.cell(0,0);shade(c,PALE_AMBER if amber else PALE_BLUE);p=c.paragraphs[0];p.paragraph_format.space_after=Pt(0);font(p.add_run(label+": "),10.5,True,NAVY);font(p.add_run(text),10.5);d.add_paragraph().paragraph_format.space_after=Pt(1)
def page_no(p):
    r=p.add_run();a,s,e=(OxmlElement("w:fldChar") for _ in range(3));a.set(qn("w:fldCharType"),"begin");s.set(qn("w:fldCharType"),"separate");e.set(qn("w:fldCharType"),"end");i=OxmlElement("w:instrText");i.set(qn("xml:space"),"preserve");i.text=" PAGE ";v=OxmlElement("w:t");v.text="1"
    for n in (a,i,s,v,e):r._r.append(n)
    font(r,8.5,color=MUTED)
def base(title,subtitle):
    d=Document();sec=d.sections[0];sec.page_width,sec.page_height=Inches(8.5),Inches(11);sec.top_margin=sec.bottom_margin=sec.left_margin=sec.right_margin=Inches(1);sec.header_distance=sec.footer_distance=Inches(.492)
    n=d.styles["Normal"];n.font.name="Calibri";n.font.size=Pt(11);n._element.rPr.rFonts.set(qn("w:ascii"),"Calibri");n._element.rPr.rFonts.set(qn("w:hAnsi"),"Calibri");n.font.color.rgb=RGBColor.from_string(INK);n.paragraph_format.space_after=Pt(6);n.paragraph_format.line_spacing=1.25
    for name,size,color,before,after in (("Heading 1",16,BLUE,18,10),("Heading 2",13,BLUE,14,7),("Heading 3",12,"1F4D78",10,5)):
        s=d.styles[name];s.font.name="Calibri";s.font.size=Pt(size);s.font.bold=True;s.font.color.rgb=RGBColor.from_string(color);s._element.rPr.rFonts.set(qn("w:ascii"),"Calibri");s._element.rPr.rFonts.set(qn("w:hAnsi"),"Calibri");s.paragraph_format.space_before=Pt(before);s.paragraph_format.space_after=Pt(after);s.paragraph_format.keep_with_next=True
    lb=d.styles["List Bullet"];lb.font.name="Calibri";lb.font.size=Pt(11);lb.paragraph_format.left_indent=Inches(.375);lb.paragraph_format.first_line_indent=Inches(-.188);lb.paragraph_format.space_after=Pt(4);lb.paragraph_format.line_spacing=1.25
    h=sec.header.paragraphs[0];h.alignment=WD_ALIGN_PARAGRAPH.RIGHT;font(h.add_run(f"GulfInfraHub  |  {title}"),8.5,True,MUTED);f=sec.footer.paragraphs[0];f.alignment=WD_ALIGN_PARAGRAPH.RIGHT;font(f.add_run("Client reference  •  August 2026  |  "),8.5,color=MUTED);page_no(f)
    para(d,"CLIENT REFERENCE",10,True,AMBER,18,WD_ALIGN_PARAGRAPH.CENTER);para(d,title,28,True,NAVY,4,WD_ALIGN_PARAGRAPH.CENTER);para(d,subtitle,15,color=BLUE,after=18,align=WD_ALIGN_PARAGRAPH.CENTER);return d
def save(d,name):
    # Remove layout-only trailing paragraphs after a final table; Pages can push
    # these onto an otherwise blank last page.
    while d.paragraphs and not d.paragraphs[-1].text.strip():
        p=d.paragraphs[-1]._element;p.getparent().remove(p)
    OUT.mkdir(exist_ok=True);p=OUT/name;d.save(p);print(p)

def common_directory(title,scope,search,filters,card,detail,create,actions,security,filename):
    d=base(f"{title} Feature Guide",scope);callout(d,"Purpose",f"Explain how users discover, evaluate, save, contact and publish {title.lower()} records in the implemented application.")
    heading(d,"1. Entry points and page purpose");grid(d,[("Header menu",f"{title} opens the public directory."),("Homepage",f"Featured/latest cards and Browse All lead into {title}."),("Directory hero","Breadcrumb, module description, keyword, Category, Country and City controls."),("Primary CTA",create[0][0]+" opens Add Listing with the relevant module selected."),("Public access","Visitors may browse published records; protected actions request authentication.")])
    heading(d,"2. Directory search and filters");para(d,search);grid(d,filters,header=("Control","Matching behaviour"));callout(d,"Filter relationship","All active conditions must match. Leaving a control empty keeps that dimension unrestricted.")
    heading(d,"3. Listing cards and result actions");grid(d,card,header=("Card element","Displayed information or action"));bullet(d,"No results","The directory shows a module-specific no-match message and asks the user to adjust or clear criteria.")
    heading(d,"4. Detail page");grid(d,detail,header=("Section","Information or action"));
    heading(d,"5. Saving and contacting");grid(d,actions);callout(d,"Saved listings","Saving requires sign-in. The record is stored against the user and is available from Saved Listings; the same control can remove it.")
    heading(d,"6. Publishing a listing");para(d,"Publishing uses the standard four-stage Add Listing workflow: select type, enter details, add media/documents, then review and publish after fresh email OTP verification.");grid(d,create,header=("Creation area","Principal fields or rule"))
    heading(d,"7. Ownership, moderation and security");grid(d,security);bullet(d,"Owner management","The signed-in owner can access the record in My Listings, edit it and delete it.");bullet(d,"Edit moderation","Saving changes returns a standard listing to Pending for administrator review.");bullet(d,"Administrator","May approve, hold, reject and—after publication—feature eligible standard listings.");callout(d,"Blocked account","An administrator-blocked account cannot create, edit, save/contact through protected workflows, or publish listings.",True)
    heading(d,"8. Client acceptance checklist");
    for a,b in (("Discovery","Test keyword, country/city and all module filters."),("Record review","Open a card and verify every detail section and document/contact action."),("Account action","Save/unsave with signed-out and signed-in users."),("Creation","Validate required fields, media limits, OTP and Pending moderation state."),("Ownership","Verify only the owner can edit/delete and that non-published records are not publicly discoverable.")):bullet(d,a,b)
    save(d,filename)

