def simple_guide(title,subtitle,filename,sections):
    d=base(title,subtitle);callout(d,"Purpose",sections.pop(0))
    for idx,(name,content) in enumerate(sections,1):
        heading(d,f"{idx}. {name}")
        if isinstance(content,str):para(d,content)
        elif content and isinstance(content[0],tuple):grid(d,content)
        else:
            for a,b in content:bullet(d,a,b)
    if filename == "GulfInfraHub_About_Us_Feature_Guide.docx":
        for table in d.tables:
            for row in table.rows:
                for cell in row.cells:
                    for p in cell.paragraphs:
                        p.paragraph_format.line_spacing=1.0
                        for run in p.runs: run.font.size=Pt(9.5)
    save(d,filename)

